program
  .command('source-day-of-week-token-mass-share')
  .description(
    'Per-source distribution of total token mass across the 7 UTC weekdays. Reports share vector (sums to 1), dominant weekday and its share, weekendShare (Sun+Sat), and ln(7)-normalized Shannon entropy. Orthogonal to weekday-share (global) and weekend-vs-weekday (global): this is per-source. Orthogonal to all hour-of-day stats (different axis) and to daily-token-* (collapses date axis, keeps 7-cycle).',
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: tokens (default) | dominant | weekend | entropy | source. Applied before --top.',
    'tokens',
  )
  .option(
    '--min-weekend-share <s>',
    'display filter: hide sources whose weekendShare (share[Sun]+share[Sat]) is strictly below s. s in [0,1]. Default 0 = no filter. Useful for surfacing only weekend-skewed sources (e.g. --min-weekend-share 0.4 hides every source at or below the 2/7 uniform baseline). Counts surface as droppedBelowMinWeekendShare.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        minTokens: string;
        top: string;
        sort: string;
        minWeekendShare: string;
        json?: boolean;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(`--top must be a non-negative integer (got ${opts.top})`);
        }
        const minWeekendShare = Number.parseFloat(opts.minWeekendShare);
        if (
          !Number.isFinite(minWeekendShare) ||
          minWeekendShare < 0 ||
          minWeekendShare > 1
        ) {
          throw new Error(
            `--min-weekend-share must be a number in [0, 1] (got ${opts.minWeekendShare})`,
          );
        }
        const validSorts = ['tokens', 'dominant', 'weekend', 'entropy', 'source'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        const report = buildSourceDayOfWeekTokenMassShare(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          top,
          minWeekendShare,
          sort: opts.sort as
            | 'tokens'
            | 'dominant'
            | 'weekend'
            | 'entropy'
            | 'source',
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(renderSourceDayOfWeekTokenMassShare(report) + '\n');
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-gini-coefficient')
  .description(
    'Per-source Gini coefficient of the per-day total_tokens distribution. Collapses hourly buckets to UTC days, then computes Gini over the day vector. Range [0, (n-1)/n]. Order-invariant — orthogonal to z-score / monotone-run / autocorrelation / 2nd-diff sign-runs which read the daily series in order.',
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--min-days <n>',
    'hide source rows whose nDays is below n (default 2); Gini on n=1 is 0 by definition. Counts surface as droppedBelowMinDays.',
    '2',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: gini (default) | tokens | days | source. Applied before --top.',
    'gini',
  )
  .option(
    '--min-gini <g>',
    'display filter: hide sources whose Gini is strictly below this value. g in [0,1]. Default 0 = no filter. Applied after --min-tokens and --min-days. Counts surface as droppedBelowMinGini.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        minTokens: string;
        minDays: string;
        top: string;
        sort: string;
        minGini: string;
        json?: boolean;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const minDays = Number.parseInt(opts.minDays, 10);
        if (!Number.isInteger(minDays) || minDays < 1) {
          throw new Error(
            `--min-days must be a positive integer (got ${opts.minDays})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(`--top must be a non-negative integer (got ${opts.top})`);
        }
        const minGini = Number.parseFloat(opts.minGini);
        if (!Number.isFinite(minGini) || minGini < 0 || minGini > 1) {
          throw new Error(
            `--min-gini must be a number in [0, 1] (got ${opts.minGini})`,
          );
        }
        const validSorts = ['gini', 'tokens', 'days', 'source'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        const report = buildDailyTokenGini(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          minDays,
          top,
          minGini,
          sort: opts.sort as 'gini' | 'tokens' | 'days' | 'source',
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(renderDailyTokenGini(report) + '\n');
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-zenga-index')
  .description(
    "Per-source ZENGA (2007) inequality index of the per-day total_tokens distribution (THIRTY-FOURTH cross-source axis). Z = (1/(n-1)) * sum_{k=1..n-1} (1 - M_k^- / M_k^+) where M_k^- is the bottom-k mean and M_k^+ is the top-(n-k) mean of the sorted day vector. Range [0, 1]. ORTHOGONAL to daily-token-gini-coefficient (Lorenz integral, single Σ over the curve) because Zenga averages (n-1) DIFFERENT bottom-vs-top mean ratios -- two day-vectors with identical Gini can have meaningfully different Zenga, and Zenga is more sensitive to mid-cutpoint shape. Also order-invariant, so orthogonal to daily-token-monotone-run-length / daily-token-second-difference-sign-runs / daily-token-autocorrelation-lag1 / daily-token-zscore-extremes; uses ALL cutpoints, so orthogonal to single-day-mass-concentration (fixed k=1,2,3) and cumulative-tokens-midpoint (single 50% quantile). Per-source columns: zenga, maxU (peak per-cutpoint inequality), argmaxK (1-indexed cutpoint achieving maxU), meanDaily, maxDay, maxDayTokens.",
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--min-days <n>',
    'hide source rows whose nDays is below n (default 2). Zenga requires n >= 2. Counts surface as droppedBelowMinDays.',
    '2',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: zenga (default) | tokens | days | source. Applied before --top.',
    'zenga',
  )
  .option(
    '--min-zenga <z>',
    'display filter: hide sources whose Zenga is strictly below this value. z in [0,1]. Default 0 = no filter.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .option(
    '--show-quantile-sweep',
    'append [quantile sweep] line per source listing u(k) at k=round(0.25*n), round(0.50*n), round(0.75*n) -- positions inside the (n-1) cutpoint range',
  )
  .option(
    '--show-curve',
    'append [per-cutpoint inequality curve] block per source listing the full u(k) for k=1..n-1 (length n-1)',
  )
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        minTokens: string;
        minDays: string;
        top: string;
        sort: string;
        minZenga: string;
        json?: boolean;
        showQuantileSweep?: boolean;
        showCurve?: boolean;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const minDays = Number.parseInt(opts.minDays, 10);
        if (!Number.isInteger(minDays) || minDays < 2) {
          throw new Error(
            `--min-days must be an integer >= 2 (got ${opts.minDays})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(
            `--top must be a non-negative integer (got ${opts.top})`,
          );
        }
        const minZenga = Number.parseFloat(opts.minZenga);
        if (!Number.isFinite(minZenga) || minZenga < 0 || minZenga > 1) {
          throw new Error(
            `--min-zenga must be a number in [0, 1] (got ${opts.minZenga})`,
          );
        }
        const validSorts = ['zenga', 'tokens', 'days', 'source'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        const report = buildDailyTokenZengaIndex(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          minDays,
          top,
          minZenga,
          sort: opts.sort as 'zenga' | 'tokens' | 'days' | 'source',
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(
            renderDailyTokenZengaIndex(report, {
              showQuantileSweep: opts.showQuantileSweep ?? false,
              showCurve: opts.showCurve ?? false,
            }) + '\n',
          );
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-pietra-ratio')
  .description(
    "Per-source PIETRA / SCHUTZ / HOOVER ratio of the per-day total_tokens distribution (THIRTY-FIFTH cross-source axis). P = (1 / (2*n*mu)) * sum_i |D_i - mu| = max_p (p - L(p)) on the Lorenz curve. Equals the FRACTION of total mass that must be transferred from above-mean days to below-mean days to flatten the distribution. Range [0, 1 - 1/n]. ORTHOGONAL to daily-token-gini-coefficient (Gini is the AREA under the Lorenz gap; Pietra is the MAX of the same gap -- two day-vectors with identical Pietra can have very different Gini and vice versa). ORTHOGONAL to daily-token-zenga-index (Zenga averages (n-1) bottom-vs-top mean ratios; Pietra averages NOTHING -- it is a single anchored max). Order-invariant, so orthogonal to daily-token-monotone-run-length / daily-token-second-difference-sign-runs / daily-token-autocorrelation-lag1 / daily-token-zscore-extremes. Mean-anchored, so orthogonal to single-day-mass-concentration (fixed top-k) and cumulative-tokens-midpoint (fixed 50% mass quantile). Per-source columns: pietra, belowMeanShare (population share at the Lorenz argmax), nBelowMean, aboveMeanLift (mean of above-mean days / overall mean).",
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--min-days <n>',
    'hide source rows whose nDays is below n (default 2). Pietra is degenerate for n < 2. Counts surface as droppedBelowMinDays.',
    '2',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: pietra (default) | tokens | days | source. Applied before --top.',
    'pietra',
  )
  .option(
    '--min-pietra <p>',
    'display filter: hide sources whose Pietra is strictly below this value. p in [0, 1]. Default 0 = no filter.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .option(
    '--show-gini-comparison',
    'compute the Gini coefficient of the same per-day vector and append gini, P/G ratio, and concentration-style classifier (point-anchored if P/G > 0.7, curve-spread if P/G < 0.55, mixed otherwise) per row. Pure compute; the Pietra <= Gini inequality is enforced. Refinement (v0.6.272).',
  )
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        minTokens: string;
        minDays: string;
        top: string;
        sort: string;
        minPietra: string;
        json?: boolean;
        showGiniComparison?: boolean;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const minDays = Number.parseInt(opts.minDays, 10);
        if (!Number.isInteger(minDays) || minDays < 2) {
          throw new Error(
            `--min-days must be an integer >= 2 (got ${opts.minDays})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(
            `--top must be a non-negative integer (got ${opts.top})`,
          );
        }
        const minPietra = Number.parseFloat(opts.minPietra);
        if (!Number.isFinite(minPietra) || minPietra < 0 || minPietra > 1) {
          throw new Error(
            `--min-pietra must be a number in [0, 1] (got ${opts.minPietra})`,
          );
        }
        const validSorts = ['pietra', 'tokens', 'days', 'source'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        const report = buildDailyTokenPietraRatio(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          minDays,
          top,
          minPietra,
          sort: opts.sort as 'pietra' | 'tokens' | 'days' | 'source',
          showGiniComparison: opts.showGiniComparison ?? false,
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(renderDailyTokenPietraRatio(report) + '\n');
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-atkinson-index')
  .description(
    "Per-source ATKINSON inequality index of the per-day total_tokens distribution at a configurable CRRA inequality-aversion parameter epsilon (THIRTY-SIXTH cross-source axis; default epsilon=0.5). A(epsilon) = 1 - EDE(epsilon)/mu where EDE is the equally-distributed-equivalent (CRRA certainty equivalent): EDE = (mean of D_i^(1-epsilon))^(1/(1-epsilon)) for epsilon != 1, and EDE = geometric mean for epsilon = 1. Range [0, 1]. Equals the FRACTION of total mass that an inequality-averse planner with CRRA preferences would give up to flatten the distribution. ORTHOGONAL to daily-token-gini-coefficient (Gini is a Lorenz integral; Atkinson is a CRRA welfare loss with strict Pigou-Dalton transfer sensitivity at every epsilon > 0). ORTHOGONAL to daily-token-pietra-ratio (Pietra is the L-infinity Lorenz gap; Atkinson is an integral of CRRA utility -- different functional class). ORTHOGONAL to daily-token-zenga-index (Zenga averages bottom-vs-top mean ratios; Atkinson uses no rank ordering). Permutation-invariant, so orthogonal to all time-ordered axes. The epsilon knob tunes sensitivity: small epsilon is top-sensitive, epsilon=1 is the log-utility / Theil-L link, large epsilon is bottom-sensitive (Rawlsian limit -> 1 - min/mean). Per-source columns: atkinson, ede (in tokens), meanDaily, zeroCollapse (true iff a single zero day pinned A=1 at epsilon>=1).",
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--epsilon <e>',
    'CRRA inequality-aversion parameter epsilon >= 0 (default 0.5). 0 = utilitarian (A=0); 0.5 = mild aversion; 1 = log utility / geometric mean; 2 = strong bottom-sensitive aversion. At epsilon >= 1, a single zero day pins A=1 (zeroCollapse).',
    '0.5',
  )
  .option(
    '--drop-zero-days',
    'remove days with total_tokens=0 BEFORE the index is computed (only relevant at epsilon >= 1; safe under hypothetical augmentation; nDroppedZeroDays surfaces per row)',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--min-days <n>',
    'hide source rows whose nDays is below n (default 2). Atkinson is degenerate for n < 2. Counts surface as droppedBelowMinDays.',
    '2',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: atkinson (default) | tokens | days | source | ede. Applied before --top.',
    'atkinson',
  )
  .option(
    '--min-atkinson <a>',
    'display filter: hide sources whose Atkinson is strictly below this value. a in [0, 1]. Default 0 = no filter.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .option(
    '--epsilon-sweep <list>',
    'comma-separated list of additional epsilon values; for each row append an epsilonSweep array of { epsilon, atkinson, ede }. Pure compute; witnesses the CRRA aversion-knob trade-off (top-sensitive at small epsilon, bottom-sensitive at large) on the same per-day vector. Example: --epsilon-sweep 0,0.25,0.5,1,2,5. Refinement (v0.6.273).',
  )
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        epsilon: string;
        dropZeroDays?: boolean;
        minTokens: string;
        minDays: string;
        top: string;
        sort: string;
        minAtkinson: string;
        json?: boolean;
        epsilonSweep?: string;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const minDays = Number.parseInt(opts.minDays, 10);
        if (!Number.isInteger(minDays) || minDays < 2) {
          throw new Error(
            `--min-days must be an integer >= 2 (got ${opts.minDays})`,
          );
        }
        const epsilon = Number.parseFloat(opts.epsilon);
        if (!Number.isFinite(epsilon) || epsilon < 0) {
          throw new Error(
            `--epsilon must be a non-negative finite number (got ${opts.epsilon})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(
            `--top must be a non-negative integer (got ${opts.top})`,
          );
        }
        const minAtkinson = Number.parseFloat(opts.minAtkinson);
        if (!Number.isFinite(minAtkinson) || minAtkinson < 0 || minAtkinson > 1) {
          throw new Error(
            `--min-atkinson must be a number in [0, 1] (got ${opts.minAtkinson})`,
          );
        }
        const validSorts = ['atkinson', 'tokens', 'days', 'source', 'ede'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        let epsilonSweep: number[] | undefined;
        if (opts.epsilonSweep) {
          epsilonSweep = opts.epsilonSweep
            .split(',')
            .map((s) => s.trim())
            .filter((s) => s.length > 0)
            .map((s) => {
              const v = Number.parseFloat(s);
              if (!Number.isFinite(v) || v < 0) {
                throw new Error(
                  `--epsilon-sweep entries must be non-negative finite numbers (got ${s})`,
                );
              }
              return v;
            });
        }
        const report = buildDailyTokenAtkinsonIndex(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          minDays,
          epsilon,
          dropZeroDays: opts.dropZeroDays ?? false,
          top,
          minAtkinson,
          sort: opts.sort as
            | 'atkinson'
            | 'tokens'
            | 'days'
            | 'source'
            | 'ede',
          epsilonSweep,
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(renderDailyTokenAtkinsonIndex(report) + '\n');
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-theil-l-index')
  .description(
    "Per-source THEIL-L (mean log deviation, MLD) of the per-day total_tokens distribution (THIRTY-SEVENTH cross-source axis). L = (1/n) * sum_i log(mu/D_i) = log(mu/GeoMean(D)). In NATS; range [0, +inf). Equivalently, KL divergence from uniform-share to empirical-share. ORTHOGONAL to daily-token-gini-coefficient (Gini is a Lorenz integral; Theil-L is a KL divergence with strict bottom-sensitivity since log(mu/D_i) blows up as D_i -> 0). ORTHOGONAL to daily-token-pietra-ratio (Pietra is L-infinity; Theil-L is L-1 over log shortfalls). ORTHOGONAL to daily-token-zenga-index (Zenga uses rank cuts; Theil-L uses log values directly). ORTHOGONAL to daily-token-atkinson-index in functional class: Atkinson is bounded in [0,1]; Theil-L is unbounded; Theil-L is ADDITIVELY DECOMPOSABLE into within+between subgroup terms with no residual, Atkinson is NOT. The two only share an ordering at Atkinson's epsilon=1 limit, where L = -log(1 - A); we surface atkinsonAtEpsilon1 for cross-validation. Permutation-invariant, so orthogonal to all time-ordered axes. Per-source columns: theilL (in nats), atkinsonAtEpsilon1, geometricMeanDaily, meanDaily, maxDay, minDay, zeroCollapse (true iff a single zero day pinned L=+inf).",
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
  .option(
    '--source <name>',
    'restrict analysis to a single source; non-matching rows surface as droppedSourceFilter',
  )
  .option(
    '--drop-zero-days',
    'remove days with total_tokens=0 BEFORE the index is computed (avoids the +inf zero-collapse; safe under hypothetical augmentation; nDroppedZeroDays surfaces per row)',
  )
  .option(
    '--min-tokens <n>',
    'hide source rows with total_tokens below n (default 1000); counts surface as droppedSparseSources',
    '1000',
  )
  .option(
    '--min-days <n>',
    'hide source rows whose nDays is below n (default 2). Theil-L is degenerate for n < 2.',
    '2',
  )
  .option(
    '--top <n>',
    'show only the top n sources after sort; remainder surface as droppedTopSources (default 0 = no cap)',
    '0',
  )
  .option(
    '--sort <key>',
    'sort key: theilL (default) | tokens | days | source | meanDaily. Applied before --top.',
    'theilL',
  )
  .option(
    '--min-theil-l <l>',
    'display filter: hide sources whose theilL is strictly below this value. l in [0, +inf). Default 0 = no filter.',
    '0',
  )
  .option('--json', 'emit JSON instead of a pretty report')
  .option(
    '--alpha-sweep <list>',
    'comma-separated list of alpha values; for each row append a geSweep array of { alpha, ge } where ge = GE(alpha) of the same per-day vector (alpha=0 -> theilL; alpha=1 -> Theil-T; alpha=2 -> half-squared-CV). Pure compute; surfaces the GE-family shape in one call. Example: --alpha-sweep 0,0.5,1,2.',
  )
  .action(
    async (
      opts: {
        since?: string;
        until?: string;
        source?: string;
        dropZeroDays?: boolean;
        minTokens: string;
        minDays: string;
        top: string;
        sort: string;
        minTheilL: string;
        json?: boolean;
        alphaSweep?: string;
      },
      cmd,
    ) => {
      try {
        const common = cmd.optsWithGlobals() as CommonOpts;
        const paths = resolvePewPaths(common.pewHome);
        const minTokens = Number.parseFloat(opts.minTokens);
        if (!Number.isFinite(minTokens) || minTokens < 0) {
          throw new Error(
            `--min-tokens must be a non-negative number (got ${opts.minTokens})`,
          );
        }
        const minDays = Number.parseInt(opts.minDays, 10);
        if (!Number.isInteger(minDays) || minDays < 2) {
          throw new Error(
            `--min-days must be an integer >= 2 (got ${opts.minDays})`,
          );
        }
        const top = Number.parseInt(opts.top, 10);
        if (!Number.isInteger(top) || top < 0) {
          throw new Error(
            `--top must be a non-negative integer (got ${opts.top})`,
          );
        }
        const minTheilL = Number.parseFloat(opts.minTheilL);
        if (!Number.isFinite(minTheilL) || minTheilL < 0) {
          throw new Error(
            `--min-theil-l must be a non-negative finite number (got ${opts.minTheilL})`,
          );
        }
        const validSorts = ['theilL', 'tokens', 'days', 'source', 'meanDaily'];
        if (!validSorts.includes(opts.sort)) {
          throw new Error(
            `--sort must be one of ${validSorts.join('|')} (got ${opts.sort})`,
          );
        }
        const queue = await readQueue(paths);
        let alphaSweep: number[] | undefined;
        if (opts.alphaSweep) {
          alphaSweep = opts.alphaSweep
            .split(',')
            .map((s) => s.trim())
            .filter((s) => s.length > 0)
            .map((s) => {
              const v = Number.parseFloat(s);
              if (!Number.isFinite(v)) {
                throw new Error(
                  `--alpha-sweep entries must be finite numbers (got ${s})`,
                );
              }
              return v;
            });
        }
        const report = buildDailyTokenTheilLIndex(queue, {
          since: opts.since ?? null,
          until: opts.until ?? null,
          source: opts.source ?? null,
          minTokens,
          minDays,
          dropZeroDays: opts.dropZeroDays ?? false,
          top,
          minTheilL,
          sort: opts.sort as
            | 'theilL'
            | 'tokens'
            | 'days'
            | 'source'
            | 'meanDaily',
          alphaSweep,
        });
        if (opts.json || common.json) {
          process.stdout.write(JSON.stringify(report, null, 2) + '\n');
        } else {
          process.stdout.write(renderDailyTokenTheilLIndex(report) + '\n');
        }
      } catch (e) {
        die(e);
      }
    },
  );

program
  .command('daily-token-theil-t-index')
  .description(
    "Per-source THEIL-T (mass-weighted entropy deviation, GE(1)) of the per-day total_tokens distribution (THIRTY-EIGHTH cross-source axis). T = sum_i q_i * log(q_i / (1/n)) = log(n) + sum q log q where q_i = D_i/sum(D). In NATS; range [0, log(n)]. Equivalently, KL divergence FROM empirical-share TO uniform-share -- the MIRROR of axis-37 Theil-L = D_KL(uniform || empirical). Because KL is asymmetric, T and L are FUNCTIONALLY INDEPENDENT. T is TOP-SENSITIVE (mass-weighted: large days dominate the sum); L is BOTTOM-SENSITIVE (uniform-weighted log shortfall: small days dominate). T remains FINITE on zero-day vectors (axis-37 zero-collapses to +inf). The headline derived field is the SKEW RATIO T/L (lInfinite=true if L=+inf): >1 means upper-tail-dominated inequality, <1 means lower-tail-dominated. Cannot be recovered from either axis alone. Per-source columns: theilT, normalisedTheilT (=T/log(n) in [0,1]), theilL (cross-anchor), tOverL (skew indicator), shannonEntropyQ (=log(n)-T), meanDaily, minDay, maxDay, lInfinite.",
  )
  .option('--since <iso>', 'inclusive ISO lower bound on hour_start')
  .option('--until <iso>', 'exclusive ISO upper bound on hour_start')
